use std::fs;

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

fn live_total() -> Result<i32, i32> {
    let wall = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse::<i32>()
        .map_err(|_| 1)?;
    let entries = fs::read_dir("/app/daywell").map_err(|_| 1)?;
    let mut paths = Vec::new();
    for entry in entries {
        let entry = entry.map_err(|_| 1)?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let digits = &name[1..9];
        if !digits.bytes().all(|b| b.is_ascii_digit()) {
            continue;
        }
        let day = digits.parse::<i32>().map_err(|_| 1)?;
        if day <= wall {
            paths.push((day, entry.path()));
        }
    }
    paths.sort_by_key(|entry| entry.0);
    let mut total = 0i32;
    for (_, path) in paths {
        let text = fs::read_to_string(path).map_err(|_| 1)?;
        let rows = text.lines().filter(|line| !line.trim().is_empty()).count();
        total = total.checked_add(i32::try_from(rows).map_err(|_| 1)?).ok_or(1)?;
    }
    Ok(total)
}

pub fn gait(pipeline_total: i32, _packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let total = match live_total() {
        Ok(total) if total > 0 && total == pipeline_total => total,
        _ => return 1,
    };
    if emit("live", total, total).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
